function PetDojo:Fill(jsonData)
    jsonData = checkTable(jsonData)
    for key, value in pairs(jsonData) do
        --只更新自己关心的数据
        if isSet(jsonData, key) and table.haskey(self, key) then
            if key == 'customSuits' then
                for i, v in ipairs(value) do
                    ---@type PetSuitDojo
                    local dojo = PetSuitDojo.New()
