function PetDojo:GetSuit(suitId)
    local suit = nil
    for i = 1, #self.customSuits do
        if self.customSuits[i].uniqueCustomSuitId == suitId then
            suit = self.customSuits[i]
            break
        end
    end
    
    return suit
end

function PetDojo:UnlockSuit(suitId)
    ---@type PetSuitDojo
    local dojo = PetSuitDojo.New()
    dojo.uniqueCustomSuitId = suitId
    table.insert(self.customSuits, dojo)
    return dojo
end

function PetDojo:AddSuit(suitId, name, parts)
    local suit = self:GetSuit(suitId)
    if suit == nil then
        suit = self:UnlockSuit(suitId)
    end
    
    suit.uniqueCustomSuitId = suitId
    suit.name = name
    suit.parts = parts
end



